-- Seed: Indicadores de 5to de Secundaria - Inglés

INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('5to', 'Inglés', 'BC1', 'IL-1', 'Responde adecuadamente a preguntas e indicaciones, a partir de la idea general y detalles específicos de textos orales y escritos de estructura sencilla y en lengua estándar, que tratan temas y situaciones cotidianas o de su interés, tales como reclamaciones, interacciones médicas, sugerencias, narraciones, expresiones de probabilidad y reportes de información, incluso si necesita releer y que le repitan.'),
('5to', 'Inglés', 'BC1', 'IL-2', 'Produce textos orales y escritos comprensibles cuya finalidad es plantear quejas y reclamaciones, comparar y contrastar, comprar, prohibir, interactuar en consultas médicas, sugerir, narrar, expresar probabilidad y reportar información, relativos a la vida diaria y a temas que le son familiares, con una pronunciación, fluidez aceptable en lo oral y posibles incorrecciones sencillas en lo escrito.'),
('5to', 'Inglés', 'BC1', 'IL-3', 'Interactúa de forma oral y escrita de forma comprensible en distintas situaciones de comunicación, sosteniendo la conversación mediante oraciones sencillas, relativas a temas cotidianos o abstractos de su interés, tales como plantear quejas y reclamaciones, comparar y contrastar, prohibir, interactuar en consultas médicas, sugerir, narrar, expresar probabilidad y reportar información.'),

-- BC2
('5to', 'Inglés', 'BC2', 'IL-4', 'Responde a preguntas e indicaciones a partir de los detalles específicos de textos orales y escritos, capaz de analizar la información, razones y puntos de vista relacionados con temas cotidianos y abstractos de su interés.'),
('5to', 'Inglés', 'BC2', 'IL-5', 'Produce textos escritos y discursos orales comprensibles que presentan información y puntos de vista coherentes, permitiendo contrastar y comparar elementos, razonamientos e ideas en diversos temas cotidianos y culturales de su interés con una estructura lógica y creativa.'),
('5to', 'Inglés', 'BC2', 'IL-6', 'Interactúa de forma sostenida en situaciones habituales de comunicación en inglés, utilizando elementos lógico-verbales para estructurar y presentar su mensaje de manera creativa y crítica, al comparar y contrastar ideas, experiencias y puntos de vista sobre temas cotidianos y abstractos de manera clara y coherente.'),
('5to', 'Inglés', 'BC2', 'IL-7', 'Plantea respuestas y alternativas a preguntas e indicaciones, a partir de la lectura o escucha de la descripción de problemas, y situaciones relativas a su entorno y temas que le son familiares, analizando puntos de vista, razonamientos, planes, instrucciones, y experiencias propias y de otras personas.'),
('5to', 'Inglés', 'BC2', 'IL-8', 'Produce textos orales y escritos sencillos y comprensibles, con capacidad para estructurar y presentar información de manera coherente y justificar posibles soluciones sobre problemas y situaciones de su entorno y temas que le son familiares, analizando puntos de vista, razonamientos, planes, instrucciones, y experiencias propias y de otras personas.'),
('5to', 'Inglés', 'BC2', 'IL-9', 'Interactúa de manera sostenida y comprensible sobre problemas y situaciones de su entorno inmediato, integrando diferentes informaciones, perspectivas y puntos de vista, argumentos y razonamientos sencillos para justificar posibles soluciones.'),

-- BC3
('5to', 'Inglés', 'BC3', 'IL-13', 'Identifica y utiliza información relevante y actualizada, y es capaz de presentarla de forma estructurada y sencilla en formato físico, digital o virtual, atendiendo a preguntas e indicaciones previstas.'),
('5to', 'Inglés', 'BC3', 'IL-14', 'Comunica información en el idioma inglés sobre temas de carácter científico y tecnológico de forma estructurada y con un vocabulario sencillo referente a temas que le son familiares, aunque con algunos errores gramaticales y de pronunciación.'),
('5to', 'Inglés', 'BC3', 'IL-15', 'Interactúa en el idioma inglés de forma sencilla y sostenida, para explicar y justificar puntos de vista sobre temas de carácter científico y tecnológico en situaciones que le son familiares o de su entorno, aunque con algunas dificultades para la fluidez y corrección gramatical.'),
('5to', 'Inglés', 'BC3', 'IL-16', 'Identifica y utiliza información relevante sobre el cuidado de la salud y el medioambiente de manera clara y coherente, con un vocabulario sencillo y adecuado.'),
('5to', 'Inglés', 'BC3', 'IL-17', 'Demuestra valoración del cuidado de la salud y el medioambiente, y es capaz de comunicarse con expresiones sencillas sobre el tema, compartiendo explicaciones, consejos y sugerencias en situaciones habituales o de su interés.'),
('5to', 'Inglés', 'BC3', 'IL-18', 'Identifica y valora las opciones que impactan el cuidado de la salud y del medioambiente, justificando acciones y su propia impresión en situaciones de interacción en inglés.'),

-- BC4
('5to', 'Inglés', 'BC4', 'IL-10', 'Analiza las diferencias y similitudes individuales y la identidad social y cultural propia y de otros países en los textos que lee o escucha.'),
('5to', 'Inglés', 'BC4', 'IL-11', 'Produce textos orales o escritos con conciencia de las diferencias individuales generales de las personas y culturas diferentes, con una buena pronunciación, fluidez y corrección aceptable.'),
('5to', 'Inglés', 'BC4', 'IL-12', 'Interactúa en el idioma inglés en situaciones habituales, con cortesía y respeto, valorando de forma crítica las diferencias individuales y la identidad sociocultural local y global.'),
('5to', 'Inglés', 'BC4', 'IL-19', 'Identifica y comprende deseos, aspiraciones, planes y experiencias personales propios y de otras personas en un plano de aceptación, cortesía, honestidad y respeto.'),
('5to', 'Inglés', 'BC4', 'IL-20', 'Expresa información, perspectivas, sugerencias, consejos e instrucciones con cortesía, respeto y tolerancia en situaciones propias de su cotidianidad y entorno.'),
('5to', 'Inglés', 'BC4', 'IL-21', 'Muestra una actitud y conducta cortés y respetuosa al interactuar en inglés sencillo pero sostenido, refiriéndose a detalles, costumbres y experiencias pasadas, consejos y sugerencias.');
